package com.tnr.cityguide.place;
import com.tnr.cityguide.city.*;import com.tnr.cityguide.common.*;import com.tnr.cityguide.favorite.*;import java.time.*;import java.util.*;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class PlaceService {
 private final PlaceRepository places;private final CityRepository cities;private final PlaceImageRepository images;private final FavoriteRepository favorites;private final Clock clock;
 public PlaceService(PlaceRepository p,CityRepository c,PlaceImageRepository i,FavoriteRepository f,Clock clock){places=p;cities=c;images=i;favorites=f;this.clock=clock;}
 @Transactional(readOnly=true) public PageResponse<PlaceDto> list(String city,String category,Double minRating,String q,String sort,int page,int size,UUID user){if(category!=null&&!Set.of("attraction","restaurant","hotel","event").contains(category))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"Unknown category.");if(!Set.of("rating","reviews","name").contains(sort))throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"Unknown sort.");if(page<0||size<1||size>100)throw new org.springframework.web.server.ResponseStatusException(org.springframework.http.HttpStatus.BAD_REQUEST,"Invalid page or size.");Sort order=switch(sort){case "reviews"->Sort.by(Sort.Order.desc("reviewCount"),Sort.Order.asc("name"),Sort.Order.asc("id"));case "name"->Sort.by(Sort.Order.asc("name").ignoreCase(),Sort.Order.asc("id"));default->Sort.by(Sort.Order.desc("ratingAvg"),Sort.Order.asc("name"),Sort.Order.asc("id"));};Page<Place> result=places.findAll(PlaceSpecifications.filters(city,category,minRating,q),PageRequest.of(page,size,order));return new PageResponse<>(result.getContent().stream().map(p->summary(p,user)).toList(),page,size,result.getTotalElements(),result.getTotalPages());}
 @Transactional(readOnly=true) public PlaceDetailDto get(String id,UUID user){Place p=places.findById(id).orElseThrow(()->new NotFoundException("Place not found."));City city=cities.findById(p.getCityId()).orElse(null);PlaceDto b=summary(p,user);List<ImageDto> imageDtos=images.findByPlaceIdOrderBySortOrderAsc(id).stream().map(i->new ImageDto(i.getId(),i.getUrl(),i.getSortOrder())).toList();return new PlaceDetailDto(b.id(),b.cityId(),b.category(),b.name(),b.description(),b.address(),b.phone(),b.website(),b.lat(),b.lng(),b.hoursText(),b.extra(),b.avgRating(),b.reviewCount(),b.isOpenNow(),b.isFavorite(),b.thumbnailUrl(),city==null?null:city.getName(),city==null?null:city.getTimezone(),p.getOpensAt(),p.getClosesAt(),p.isOpen24h(),p.getClosedDays()==null?List.of():java.util.stream.IntStream.range(0,p.getClosedDays().length).mapToObj(i->p.getClosedDays()[i]).toList(),imageDtos);}
 @Transactional(readOnly=true) public PlaceDto getSummary(String id,UUID user){Place p=places.findById(id).orElseThrow(()->new NotFoundException("Place not found."));return summary(p,user);}
 private PlaceDto summary(Place p,UUID user){City city=cities.findById(p.getCityId()).orElse(null);Boolean open=city==null?null:OpeningHours.isOpen(p,ZoneId.of(city.getTimezone()),Instant.now(clock));String thumbnail=images.findByPlaceIdOrderBySortOrderAsc(p.getId()).stream().findFirst().map(PlaceImage::getUrl).orElse(null);boolean favourite=user!=null&&favorites.existsById(new Favorite.Key(user,p.getId()));return new PlaceDto(p.getId(),p.getCityId(),p.getCategory(),p.getName(),p.getDescription(),p.getAddress(),p.getPhone(),p.getWebsite(),p.getLat(),p.getLng(),p.getHoursText(),p.getExtra(),p.getRatingAvg(),p.getReviewCount(),open,favourite,thumbnail);}
 public record PlaceDto(String id,String cityId,String category,String name,String description,String address,String phone,String website,double lat,double lng,String hoursText,String extra,double avgRating,int reviewCount,Boolean isOpenNow,boolean isFavorite,String thumbnailUrl){}
 public record PlaceDetailDto(String id,String cityId,String category,String name,String description,String address,String phone,String website,double lat,double lng,String hoursText,String extra,double avgRating,int reviewCount,Boolean isOpenNow,boolean isFavorite,String thumbnailUrl,String cityName,String timezone,LocalTime opensAt,LocalTime closesAt,boolean open24h,List<Short> closedDays,List<ImageDto> images){}
 public record ImageDto(UUID id,String url,int sortOrder){}
}